-- ==========================================
-- 5. BOOKINGS & LOGS
-- ==========================================
CREATE TABLE bookings (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    requester_profile_id UUID NOT NULL REFERENCES requester_profiles(id) ON DELETE CASCADE,
    interpreter_profile_id UUID REFERENCES interpreter_profiles(id) ON DELETE CASCADE,
    service_id UUID REFERENCES services(id) ON DELETE CASCADE,
    status TEXT NOT NULL DEFAULT 'pending', -- pending, accepted, rejected, completed, cancelled, in_progress
    scheduled_date TIMESTAMPTZ NOT NULL,
    duration_minutes INTEGER NOT NULL,
    total_amount NUMERIC(10, 2) NOT NULL,
    currency TEXT NOT NULL DEFAULT 'AOA',
    location_type TEXT NOT NULL, -- online, presencial
    meeting_link TEXT,
    address TEXT,
    notes TEXT,
    created_at TIMESTAMPTZ DEFAULT timezone('utc'::text, now()),
    updated_at TIMESTAMPTZ DEFAULT timezone('utc'::text, now())
);

CREATE TABLE booking_logs (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    booking_id UUID NOT NULL REFERENCES bookings(id) ON DELETE CASCADE,
    old_status TEXT,
    new_status TEXT NOT NULL,
    changed_by_user_id UUID NOT NULL REFERENCES users(id) ON DELETE CASCADE,
    reason TEXT,
    created_at TIMESTAMPTZ DEFAULT timezone('utc'::text, now()),
    updated_at TIMESTAMPTZ DEFAULT timezone('utc'::text, now())
);

CREATE TABLE chat_messages (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    booking_id UUID NOT NULL REFERENCES bookings(id) ON DELETE CASCADE,
    sender_id UUID NOT NULL REFERENCES users(id) ON DELETE CASCADE,
    content TEXT NOT NULL,
    read_at TIMESTAMPTZ,
    attachment_url TEXT,
    attachment_type TEXT, -- image, file
    created_at TIMESTAMPTZ DEFAULT timezone('utc'::text, now()),
    updated_at TIMESTAMPTZ DEFAULT timezone('utc'::text, now())
);

CREATE TABLE reviews (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    booking_id UUID NOT NULL REFERENCES bookings(id) ON DELETE CASCADE,
    -- Bidirectional specific relation
    author_interpreter_id UUID REFERENCES interpreter_profiles(id) ON DELETE CASCADE,
    author_requester_id UUID REFERENCES requester_profiles(id) ON DELETE CASCADE,
    target_interpreter_id UUID REFERENCES interpreter_profiles(id) ON DELETE CASCADE,
    target_requester_id UUID REFERENCES requester_profiles(id) ON DELETE CASCADE,
    rating INTEGER NOT NULL CHECK (rating BETWEEN 1 AND 5),
    comment TEXT,
    is_visible BOOLEAN DEFAULT true,
    created_at TIMESTAMPTZ DEFAULT timezone('utc'::text, now()),
    updated_at TIMESTAMPTZ DEFAULT timezone('utc'::text, now()),
    -- Ensure cross review
    CONSTRAINT reviews_author_check CHECK (
        (author_interpreter_id IS NOT NULL AND author_requester_id IS NULL) OR
        (author_interpreter_id IS NULL AND author_requester_id IS NOT NULL)
    ),
    CONSTRAINT reviews_target_check CHECK (
        (target_interpreter_id IS NOT NULL AND target_requester_id IS NULL) OR
        (target_interpreter_id IS NULL AND target_requester_id IS NOT NULL)
    ),
    UNIQUE(booking_id, author_interpreter_id, author_requester_id)
);

CREATE TABLE favorites (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    requester_profile_id UUID NOT NULL REFERENCES requester_profiles(id) ON DELETE CASCADE,
    interpreter_profile_id UUID NOT NULL REFERENCES interpreter_profiles(id) ON DELETE CASCADE,
    created_at TIMESTAMPTZ DEFAULT timezone('utc'::text, now()),
    UNIQUE(requester_profile_id, interpreter_profile_id)
);

-- ==========================================
-- 6. FINANCE (PAYMENTS & PAYOUTS)
-- ==========================================
CREATE TABLE payments (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    booking_id UUID NOT NULL REFERENCES bookings(id) ON DELETE CASCADE,
    requester_profile_id UUID NOT NULL REFERENCES requester_profiles(id) ON DELETE CASCADE,
    amount NUMERIC(10, 2) NOT NULL,
    currency TEXT NOT NULL,
    status TEXT NOT NULL, -- pending, completed, failed, refunded
    method TEXT NOT NULL, -- credit_card, bank_transfer, multicaixa
    provider_transaction_id TEXT,
    receipt_url TEXT,
    created_at TIMESTAMPTZ DEFAULT timezone('utc'::text, now()),
    updated_at TIMESTAMPTZ DEFAULT timezone('utc'::text, now())
);

CREATE TABLE payouts (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    interpreter_id UUID NOT NULL REFERENCES interpreter_profiles(id) ON DELETE CASCADE,
    amount NUMERIC(10, 2) NOT NULL,
    currency TEXT NOT NULL,
    status TEXT NOT NULL, -- pending, processing, completed, failed
    iban TEXT NOT NULL,
    bank_name TEXT,
    reference TEXT,
    processed_at TIMESTAMPTZ,
    created_at TIMESTAMPTZ DEFAULT timezone('utc'::text, now()),
    updated_at TIMESTAMPTZ DEFAULT timezone('utc'::text, now())
);

