    interpreter_profile_id UUID REFERENCES interpreter_profiles(id) ON DELETE CASCADE,
    requester_profile_id UUID REFERENCES requester_profiles(id) ON DELETE CASCADE,
    admin_profile_id UUID REFERENCES admin_profiles(id) ON DELETE CASCADE,
    title TEXT NOT NULL,
    message TEXT NOT NULL,
    type TEXT NOT NULL, -- info, warning, success, error, booking_update
    action_url TEXT,
    metadata JSONB NOT NULL DEFAULT '{}'::jsonb,
    created_at TIMESTAMPTZ DEFAULT timezone('utc'::text, now()),
    updated_at TIMESTAMPTZ DEFAULT timezone('utc'::text, now())
);

CREATE TABLE system_configs (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    key TEXT NOT NULL UNIQUE,
    value TEXT NOT NULL,
    value_type TEXT NOT NULL, -- string, number, boolean, json
    label TEXT NOT NULL,
    description TEXT,
    "group" TEXT NOT NULL,
    is_public BOOLEAN DEFAULT false,
    updated_by_user_id UUID REFERENCES users(id) ON DELETE SET NULL,
    created_at TIMESTAMPTZ DEFAULT timezone('utc'::text, now()),
    updated_at TIMESTAMPTZ DEFAULT timezone('utc'::text, now())
);

